const allRows = $input.all();

// 1. Lọc các dòng có Status == 'PENDING'
const pendingRows = allRows.filter(item => {
  const status = String(item.json.Status ?? item.json.status ?? '').trim().toUpperCase();
  return status === 'PENDING';
});

// CASE D: Không có dòng PENDING nào -> kết thúc bình thường không lỗi
if (pendingRows.length === 0) {
  return [];
}

// 2. Chỉ lấy dòng PENDING đầu tiên
const firstTask = pendingRows[0].json;

// 3. Lấy ID thật từ Google Sheet, TUYỆT ĐỐI KHÔNG tự sinh ID giả
const rawId = String(firstTask.ID ?? firstTask.id ?? '').trim();

// 4. Normalize Keyword: loại bỏ whitespace, khoảng trắng thuần túy coi là rỗng
const cleanKeyword = String(firstTask.Keyword ?? firstTask.keyword ?? '').trim();

// 5. Phân loại validation
let validationResult = 'VALID';
let errorMessage = '';

if (!rawId) {
  validationResult = 'ID_EMPTY';
  errorMessage = 'ID is empty';
} else if (!cleanKeyword) {
  validationResult = 'KEYWORD_EMPTY';
  errorMessage = 'Keyword is empty';
}

return [{
  json: {
    ID: rawId,
    row_number: firstTask.row_number,
    Keyword: cleanKeyword,
    Status: 'PENDING',
    Created_At: firstTask.Created_At || firstTask.created_at || '',
    validation_result: validationResult,
    error_message: errorMessage
  }
}];

// STEP C1: Khôi phục toàn bộ business context từ node gốc
const originalTask = $('Filter & Take First PENDING Task').first().json;
const config = $('Workflow Config').first().json;

return [{
  json: {
    ID: originalTask.ID,
    row_number: originalTask.row_number,
    Keyword: originalTask.Keyword,
    Created_At: originalTask.Created_At,
    Status: 'PROCESSING',
    website_source_url: config.website_source_url || 'https://wifim.vn'
  }
}];

// STEP C3: Làm sạch và chuẩn hóa dữ liệu nguồn WIFIM
const context = $('Restore Task Context').first().json;
const responseItem = $input.first().json || {};
const targetUrl = context.website_source_url || 'https://wifim.vn';

let rawData = '';
if (typeof responseItem === 'string') {
  rawData = responseItem;
} else if (responseItem.data && typeof responseItem.data === 'string') {
  rawData = responseItem.data;
} else if (responseItem.body && typeof responseItem.body === 'string') {
  rawData = responseItem.body;
} else {
  rawData = JSON.stringify(responseItem);
}

// Kiểm tra nếu có lỗi HTTP hoặc rỗng
const hasHttpError = Boolean(responseItem.error || responseItem.statusCode >= 400 || !rawData || rawData === '{}');

let cleanedText = '';
let sourceFetchStatus = 'success';
let sourcesUsed = [];
let researchMode = 'SOURCE_PLUS_LLM_INFERENCE';
let searchIntentBasis = 'keyword_and_source_inference';
let sourceWarning = '';

if (hasHttpError) {
  sourceFetchStatus = 'failed';
  sourcesUsed = [];
  researchMode = 'LLM_INFERENCE_ONLY';
  searchIntentBasis = 'keyword_only_inference';
  sourceWarning = 'WIFIM source could not be fetched';
  cleanedText = '';
} else {
  sourceFetchStatus = 'success';
  sourcesUsed = [targetUrl];
  researchMode = 'SOURCE_PLUS_LLM_INFERENCE';
  searchIntentBasis = 'keyword_and_source_inference';
  sourceWarning = '';

  // Tiến hành làm sạch HTML có cấu trúc
  let text = rawData;
  text = text.replace(/<!--[\s\S]*?-->/g, '');
  text = text.replace(/<!DOCTYPE[^>]*>/gi, '');
  text = text.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, ' ');
  text = text.replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, ' ');
  text = text.replace(/<noscript\b[^<]*(?:(?!<\/noscript>)<[^<]*)*<\/noscript>/gi, ' ');
  text = text.replace(/<(?:nav|header|footer|svg)\b[^<]*(?:(?!<\/(?:nav|header|footer|svg)>)<[^<]*)*<\/(?:nav|header|footer|svg)>/gi, ' ');
  text = text.replace(/<\/?[a-z][a-z0-9]*[^<>]*>/gi, '\n');
  text = text.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'");
  text = text.split('\n').map(l => l.trim()).filter(l => l.length > 0).join('\n');

  // Giới hạn trong khoảng 2500 - 3000 ký tự
  cleanedText = text.slice(0, 3000);
}

return [{
  json: {
    ID: context.ID,
    row_number: context.row_number,
    Keyword: context.Keyword,
    Created_At: context.Created_At,
    Status: 'PROCESSING',
    cleaned_source_text: cleanedText,
    sources_used: sourcesUsed,
    source_fetch_status: sourceFetchStatus,
    source_warning: sourceWarning,
    research_mode: researchMode,
    search_intent_basis: searchIntentBasis
  }
}];

const item = $input.first().json;

let raw =
  item.text ??
  item.output ??
  item.response ??
  item;

let parsed;

if (
  typeof raw === 'object' &&
  raw !== null &&
  !Array.isArray(raw)
) {
  parsed = raw;
} else {
  raw = String(raw ?? '').trim();

  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1) {
    raw = raw.slice(firstBrace, lastBrace + 1);
  }

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(
      'AI Research returned invalid JSON: ' +
      raw.slice(0, 500)
    );
  }
}

const research =
  parsed.output &&
  typeof parsed.output === 'object'
    ? parsed.output
    : parsed;

return [{
  json: {
    output: {
      search_intent: String(
        research.search_intent ?? ''
      ).trim(),

      brand_context: String(
        research.brand_context ?? ''
      ).trim(),

      related_keywords:
        Array.isArray(research.related_keywords)
          ? research.related_keywords
              .map(v => String(v).trim())
              .filter(Boolean)
          : [],

      analysis_summary: String(
        research.analysis_summary ?? ''
      ).trim()
    }
  }
}];

// STEP C5: Chuẩn hóa và bảo toàn ID dòng trước khi lưu vào Google Sheet
const taskContext = $('Restore Task Context').first().json;
const cleanData = $('Clean Source Data').first().json;
const aiOutput = $input.first().json.output || $input.first().json;

// Đảm bảo tuân thủ nghiêm ngặt quy tắc schema
const researchObject = {
  search_intent: aiOutput.search_intent || '',
  search_intent_basis: cleanData.search_intent_basis,
  brand_context: cleanData.source_fetch_status === 'failed' ? '' : (aiOutput.brand_context || ''),
  competitor_analysis: '',
  people_also_ask: [],
  top_urls: [],
  related_keywords: Array.isArray(aiOutput.related_keywords) ? aiOutput.related_keywords : [],
  related_keywords_source: 'llm_suggestion',
  analysis_summary: aiOutput.analysis_summary || '',
  sources_used: cleanData.sources_used,
  source_fetch_status: cleanData.source_fetch_status,
  source_warning: cleanData.source_warning,
  research_mode: cleanData.research_mode
};

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: taskContext.Keyword,
    Status: 'PROCESSING',
    Research_Result: JSON.stringify(researchObject, null, 2)
  }
}];

// STEP D1 & D2: Khôi phục task context và chuẩn bị Research Object
const taskContext = $('Filter & Take First PENDING Task').first().json;
const formatResearchNode = $('Format Research Result').first().json;

const rawResearch = formatResearchNode.Research_Result;
if (!rawResearch || typeof rawResearch !== 'string' || !rawResearch.trim()) {
  throw new Error('Research_Result is empty in STEP D');
}

let researchObj;
try {
  researchObj = JSON.parse(rawResearch);
} catch (e) {
  throw new Error('Research_Result is invalid JSON in STEP D: ' + String(rawResearch).slice(0, 300));
}

if (!researchObj || typeof researchObj !== 'object' || !researchObj.search_intent || !String(researchObj.search_intent).trim()) {
  throw new Error('Research_Result missing valid search_intent in STEP D');
}

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: taskContext.Keyword,
    Status: 'PROCESSING',
    Research_Result: rawResearch,
    search_intent: String(researchObj.search_intent || '').trim(),
    brand_context: String(researchObj.brand_context || '').trim(),
    related_keywords: Array.isArray(researchObj.related_keywords) ? researchObj.related_keywords : [],
    analysis_summary: String(researchObj.analysis_summary || '').trim(),
    research_mode: String(researchObj.research_mode || '').trim(),
    sources_used: Array.isArray(researchObj.sources_used) ? researchObj.sources_used : [],
    competitor_analysis: String(researchObj.competitor_analysis || '').trim(),
    people_also_ask: Array.isArray(researchObj.people_also_ask) ? researchObj.people_also_ask : [],
    top_urls: Array.isArray(researchObj.top_urls) ? researchObj.top_urls : []
  }
}];

const item = $input.first().json;

let raw =
  item.text ??
  item.output ??
  item.response ??
  item;

let parsed;

if (typeof raw === 'object' && raw !== null && !Array.isArray(raw)) {
  parsed = raw;
} else {
  raw = String(raw ?? '').trim();
  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const firstBrace = raw.indexOf('{');
  const lastBrace = raw.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1) {
    raw = raw.slice(firstBrace, lastBrace + 1);
  }

  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error('AI Outline returned invalid JSON: ' + raw.slice(0, 500));
  }
}

const data =
  parsed.output && typeof parsed.output === 'object' && !Array.isArray(parsed.output)
    ? parsed.output
    : parsed;

const title = String(data.title ?? '').trim();
const metaDescription = String(data.meta_description ?? data.metaDescription ?? '').trim();
const slug = String(data.slug ?? '').trim();

if (!title) {
  throw new Error('AI Outline returned invalid JSON: Missing or empty title');
}
if (!metaDescription) {
  throw new Error('AI Outline returned invalid JSON: Missing or empty meta_description');
}
if (!slug) {
  throw new Error('AI Outline returned invalid JSON: Missing or empty slug');
}
if (!Array.isArray(data.outline) || data.outline.length === 0) {
  throw new Error('AI Outline returned invalid JSON: outline must be a non-empty array');
}

const validatedOutline = data.outline.map((item, idx) => {
  if (!item || typeof item !== 'object') {
    throw new Error(`AI Outline returned invalid JSON: outline item at index ${idx} is not an object`);
  }
  const heading2 = String(item.heading2 ?? item.h2 ?? '').trim();
  if (!heading2) {
    throw new Error(`AI Outline returned invalid JSON: outline item at index ${idx} missing heading2`);
  }
  const rawSubs = Array.isArray(item.subheadings)
    ? item.subheadings
    : Array.isArray(item.sub_headings)
      ? item.sub_headings
      : [];

  const subheadings = rawSubs.map((sub) => {
    if (typeof sub === 'string') {
      return { heading3: sub.trim() };
    }
    if (sub && typeof sub === 'object') {
      return { heading3: String(sub.heading3 ?? sub.h3 ?? '').trim() };
    }
    return { heading3: '' };
  }).filter(s => s.heading3.length > 0);

  return {
    heading2: heading2,
    subheadings: subheadings
  };
});

return [{
  json: {
    output: {
      title: title,
      meta_description: metaDescription,
      slug: slug,
      outline: validatedOutline
    }
  }
}];

// STEP D5: Format kết quả Outline và giữ task context
const taskContext = $('Restore Outline Context').first().json;
const outlineData = $input.first().json.output;

let formattedOutline = '';
for (const section of outlineData.outline) {
  formattedOutline += `H2: ${section.heading2}\n`;
  if (Array.isArray(section.subheadings)) {
    for (const sub of section.subheadings) {
      formattedOutline += `    H3: ${sub.heading3}\n`;
    }
  }
  formattedOutline += '\n';
}
formattedOutline = formattedOutline.trim();

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: taskContext.Keyword,
    Status: 'PROCESSING',
    Title: outlineData.title,
    Meta_Description: outlineData.meta_description,
    meta_description: outlineData.meta_description,
    Slug: outlineData.slug,
    Outline: JSON.stringify(outlineData.outline, null, 2),
    formatted_outline: formattedOutline
  }
}];

// STEP E1: Khôi phục toàn bộ context ổn định cho Article Writer
const taskContext = $('Filter & Take First PENDING Task').first().json;
const researchNode = $('Format Research Result').first().json;
const outlineNode = $('Format Outline Result').first().json;

const rawResearch = researchNode.Research_Result || '';
let researchObj = {};
try {
  researchObj = typeof rawResearch === 'string' ? JSON.parse(rawResearch) : rawResearch;
} catch (e) {
  researchObj = {};
}

const keyword = String(taskContext.Keyword || '').trim();
const title = String(outlineNode.Title || '').trim();
const formattedOutline = String(outlineNode.formatted_outline || '').trim();
const searchIntent = String(researchObj.search_intent || '').trim();

if (!keyword) {
  throw new Error('Restore Article Context: Missing Keyword');
}
if (!title) {
  throw new Error('Restore Article Context: Missing Title');
}
if (!formattedOutline) {
  throw new Error('Restore Article Context: Missing formatted_outline');
}
if (!searchIntent) {
  throw new Error('Restore Article Context: Missing search_intent');
}

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: keyword,
    Status: 'PROCESSING',
    Title: title,
    Meta_Description: String(outlineNode.Meta_Description || outlineNode.meta_description || '').trim(),
    Slug: String(outlineNode.Slug || outlineNode.slug || '').trim(),
    Outline: outlineNode.Outline,
    formatted_outline: formattedOutline,
    Research_Result: rawResearch,
    search_intent: searchIntent,
    brand_context: String(researchObj.brand_context || '').trim(),
    related_keywords: Array.isArray(researchObj.related_keywords) ? researchObj.related_keywords : [],
    analysis_summary: String(researchObj.analysis_summary || '').trim(),
    research_mode: String(researchObj.research_mode || '').trim(),
    sources_used: Array.isArray(researchObj.sources_used) ? researchObj.sources_used : []
  }
}];

const item = $input.first().json;
const taskContext = $('Restore Article Context').first().json;

let raw =
  item.text ??
  item.output ??
  item.response ??
  item;

let article = '';
if (typeof raw === 'object' && raw !== null) {
  article = String(raw.article ?? raw.content ?? raw.html ?? JSON.stringify(raw));
} else {
  article = String(raw ?? '');
}

// 1. Remove code fence if present
article = article.trim();
article = article
  .replace(/^```(?:html)?\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

// Strip wrapper html/head/body tags if model wrapped them
article = article.replace(/<\/?(?:html|head|body)[^>]*>/gi, '').trim();

// 2. Validation
if (!article) {
  throw new Error('AI Write Article returned empty content');
}

if (article.length < 1500) {
  throw new Error(`AI Write Article content too short: ${article.length} characters (minimum required 1500)`);
}

if (!/<h1\b[^>]*>/i.test(article)) {
  throw new Error('AI Write Article content missing <h1> heading');
}

const h2Matches = article.match(/<h2\b[^>]*>/gi);
if (!h2Matches || h2Matches.length < 2) {
  throw new Error(`AI Write Article content must contain at least 2 <h2> headings (found ${h2Matches ? h2Matches.length : 0})`);
}

if (/```/.test(article)) {
  throw new Error('AI Write Article content contains unclosed markdown code fences (```)');
}

if (/As an AI\b/i.test(article)) {
  throw new Error('AI Write Article contains forbidden AI disclaimer phrase ("As an AI")');
}

if (/T\u00f4i kh\u00f4ng th\u1ec3/i.test(article)) {
  throw new Error('AI Write Article contains refusal phrase ("Tôi không thể")');
}

// 3. QA Warnings (for logging/debug, not blocking)
const qaWarnings = [];
const checkPhrases = ['cam k\u1ebft', '\u0111\u1ea3m b\u1ea3o', 's\u1ed1 1', 't\u1ed1t nh\u1ea5t', 'duy nh\u1ea5t'];
for (const phrase of checkPhrases) {
  const reg = new RegExp(phrase, 'gi');
  const count = (article.match(reg) || []).length;
  if (count > 0) {
    qaWarnings.push(`Found phrase "${phrase}" ${count} time(s)`);
  }
}

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: taskContext.Keyword,
    Status: 'PROCESSING',
    Title: taskContext.Title,
    Meta_Description: taskContext.Meta_Description,
    Slug: taskContext.Slug,
    Article_HTML: article,
    article_length: article.length,
    qa_warnings: qaWarnings
  }
}];

// STEP F2: Chuẩn bị nội dung file HTML và tạo binary upload
const articleData = $('Validate Article HTML').first().json;
const folderData = $input.first().json;
const folderId = folderData.id || folderData.folder_id || '';

const metaDescHtml = articleData.Meta_Description 
  ? `<p><strong>Meta Description:</strong> ${articleData.Meta_Description}</p>\n`
  : '';
const fullHtml = `${metaDescHtml}${articleData.Article_HTML}`;
const fileName = `${articleData.Slug || 'bai-viet'}.html`;

return [{
  json: {
    ID: articleData.ID,
    row_number: articleData.row_number,
    Keyword: articleData.Keyword,
    Status: 'PROCESSING',
    Title: articleData.Title,
    Meta_Description: articleData.Meta_Description,
    Slug: articleData.Slug,
    folder_id: folderId,
    file_name: fileName
  },
  binary: {
    data: {
      data: Buffer.from(fullHtml, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: fileName
    }
  }
}];

// STEP F4: Trích xuất Drive URL và tạo timestamp hoàn tất
const taskContext = $('Validate Article HTML').first().json;
const fileData = $input.first().json;
const fileId = fileData.id || '';

let driveUrl = '';
if (fileData.webViewLink) {
  driveUrl = fileData.webViewLink;
} else if (fileId) {
  driveUrl = `https://drive.google.com/open?id=${fileId}`;
}

const folderData = $('Create Article Folder').first().json;
const folderId = folderData.id || '';
const folderUrl = folderData.webViewLink || (folderId ? `https://drive.google.com/drive/folders/${folderId}` : '');

// Timestamp Asia/Ho_Chi_Minh (GMT+7)
const now = new Date();
const offsetMs = 7 * 60 * 60 * 1000;
const localTime = new Date(now.getTime() + offsetMs);
const completedAt = localTime.toISOString().replace('T', ' ').substring(0, 19);

return [{
  json: {
    ID: taskContext.ID,
    row_number: taskContext.row_number,
    Keyword: taskContext.Keyword,
    Status: 'DONE',
    Drive_URL: driveUrl,
    Drive_Folder_URL: folderUrl,
    Completed_At: completedAt,
    Error_Message: ''
  }
}];
